using System;using System.Collections.Generic;using System.Drawing;using System.Runtime.InteropServices;using System.Windows.Forms;
internal static class TestDesktopPointerInput {
 static int checks;static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 [DllImport("user32.dll")]static extern uint GetRegisteredRawInputDevices([Out]DesktopRawMouseInput.Device[] devices,ref uint count,uint size);
 static bool Registered(IntPtr target){uint count=0,size=(uint)Marshal.SizeOf(typeof(DesktopRawMouseInput.Device));GetRegisteredRawInputDevices(null,ref count,size);if(count==0)return false;var devices=new DesktopRawMouseInput.Device[count];if(GetRegisteredRawInputDevices(devices,ref count,size)==UInt32.MaxValue)throw new Exception("Cannot inspect registrations");foreach(var device in devices)if(device.page==1&&device.usage==2&&device.target==target&&device.flags==0x100)return true;return false;}
 [STAThread]static void Main(){
  double now=0;var sent=new List<DesktopPointerDelivery.Packet>();var queue=new DesktopPointerDelivery(value=>sent.Add((DesktopPointerDelivery.Packet)value),()=>now);
  queue.Offer(new Point(1,2),false);Check(sent.Count==1,"initial pointer is sent once");int first=sent[0].sequence;
  for(int i=0;i<1000;i++){now=i*.1;queue.Offer(new Point(i,2),false);}Check(sent.Count==1,"high frequency input retains one in-flight packet and latest coordinate");
  queue.Acknowledge(first);Check(sent.Count==2&&sent[1].x==999,"receiver acknowledgement releases only the latest coordinate");int second=sent[1].sequence;
  queue.Acknowledge(first);Check(sent.Count==2,"obsolete acknowledgement cannot release another packet");queue.Acknowledge(second);now+=1;queue.Offer(new Point(1000,2),true);Check(sent.Count==2,"new acknowledged pointer still observes eight millisecond spacing");now+=8;queue.Offer(new Point(1000,2),true);Check(sent.Count==3&&sent[2].down,"fallback tick delivers final coordinate and button state");
  now+=750;queue.Offer(new Point(1001,2),false);Check(sent.Count==4&&sent[2].sequence!=sent[3].sequence&&!sent[3].down,"timeout resends the latest release with a fresh sequence");
  for(int i=0;i<1000;i++){now+=10;queue.Offer(new Point(2000+i,2),false);}Check(sent.Count==17,"timeout recovery stays rate limited across consecutive losses");
  int previous=sent[sent.Count-1].sequence;queue.Acknowledge(sent[3].sequence);Check(sent.Count==17,"late acknowledgement cannot clear the newest in-flight packet");
  queue.Acknowledge(previous);Check(sent.Count==18&&sent[17].x==2999,"fresh acknowledgement resumes with the latest coordinate");previous=sent[17].sequence;queue.Reset();queue.Acknowledge(previous);queue.Offer(new Point(-15,30),false);Check(sent.Count==19&&sent[18].sequence!=previous&&sent[18].x==-15,"pause reset rejects old ACK and supports negative monitor coordinates");
  using(var form=new Form()){IntPtr handle=form.Handle;using(var raw=new DesktopRawMouseInput(handle,()=>{throw new Exception("No input should be dispatched during registration check");})){raw.Enable(true);Check(raw.Registered&&Registered(handle),"real hidden HWND registers one mouse INPUTSINK without suppressing legacy input");using(var secondWindow=new Form())using(var other=new DesktopRawMouseInput(secondWindow.Handle,()=>{})){other.Enable(true);Check(!other.Registered&&Registered(handle),"another host cannot steal an existing process mouse registration");}Check(Registered(handle),"disposing an unregistered host preserves the current receiver");raw.Enable(false);Check(!raw.Registered&&!Registered(handle),"lock/suspend unregisters with REMOVE and a null target");raw.Enable(true);raw.Dispose();Check(!Registered(handle),"disposal removes the real process registration");raw.Enable(true);Check(!Registered(handle),"disposed receiver cannot re-register");}}
  Console.WriteLine(checks+" desktop pointer checks passed; no visible window, hook, cursor movement or user settings changed.");
 }
}
